# --- curriculum: external_merge_sort ---
# generated by `python -m Utils.sync` from curriculum/ -- edit there, not here
#
# EXTERNAL MERGE SORT  (Sorting / external)
#
# MENTAL MODEL
#   The data does not fit in RAM. Pass 1: read chunks that do fit, sort each
#   in memory, write them back as sorted runs. Pass 2: k-way merge all runs
#   with a heap holding one pending value per run. Peak memory is O(chunk +
#   runs), independent of total size.
#
# INVARIANT
#   Every chunk file is internally sorted, and the merge heap's root is
#   always the globally smallest unemitted value.
#
# COMPLEXITY  best O(n log n) | avg O(n log n) | worst O(n log n)
# SPACE       O(chunk + k) in memory
# PROPERTIES  stable yes  in-place no  adaptive no
#
# REACH FOR IT WHEN
#   Input exceeds memory — log files, database sort-merge joins, ETL
#   pipelines.
#
# AVOID WHEN
#   Data fits in memory. The I/O constant factor is enormous.
#
# PITFALLS
#   1. The merge must stream (one line per run in memory). Reading whole
#      runs in defeats the entire purpose.
#   2. Chunk files are temporary state and must be cleaned up; an earlier
#      version wrote chunk_*.txt into the working directory and left them
#      behind, which also made concurrent calls collide.
#   3. Real systems tune chunk_size to available RAM and k to the OS file
#      descriptor limit — k is not free.
#
# SEE ALSO    merge_sort, polyphase_sort, min_heap
#
# INTERVIEW
#   - Sort a 100GB file with 1GB of RAM
#   - Merge k Sorted Lists (LC 23) — the in-memory core
#   - Find the median of a file too large to load
# --- end curriculum ---

"""
External merge sort — sorting data that does not fit in RAM.

Two phases:
  1. Split the input into chunks small enough to sort in memory, sort each, and
     write it back out as a sorted run.
  2. K-way merge all the runs in one streaming pass, holding only a single
     pending value per run in memory at a time.

The per-chunk sort deliberately uses the builtin `list.sort`: external sorting
is about the I/O pattern, not about re-deriving a comparison sort. What matters
is that peak memory is O(chunk_size + number_of_runs), independent of the total
input size.
"""

import heapq
import os
import tempfile

DEFAULT_CHUNK_SIZE = 1000


def split_and_sort(input_file: str, chunk_size: int, work_dir: str) -> list[str]:
    """
    Split `input_file` into sorted run files of at most `chunk_size` lines each.

    Returns the run file paths in creation order.

    Time:  O(n log(chunk_size)) comparisons, O(n) I/O
    Space: O(chunk_size) in memory
    """
    chunk_files: list[str] = []
    chunk: list[int] = []

    def flush() -> None:
        chunk.sort()
        path = os.path.join(work_dir, f"chunk_{len(chunk_files)}.txt")
        with open(path, "w", encoding="utf-8") as cf:
            cf.write("".join(f"{num}\n" for num in chunk))
        chunk_files.append(path)
        chunk.clear()

    with open(input_file, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            chunk.append(int(line))
            if len(chunk) == chunk_size:
                flush()

    if chunk:
        flush()

    return chunk_files


def merge_sorted_files(chunk_files: list[str], output_file: str) -> None:
    """
    K-way merge already-sorted `chunk_files` into `output_file`.

    A min-heap holds exactly one pending value per open run, so the next value
    to emit is always at the heap root. This is the step that lets the whole
    sort run in bounded memory.

    Time:  O(n log k) for n values across k runs
    Space: O(k) — one heap entry per run
    """
    handles = [open(path, encoding="utf-8") for path in chunk_files]
    try:
        # Entries are (value, run_index); the index breaks ties so equal values
        # never force a comparison of anything non-comparable.
        heap: list[tuple] = []
        for idx, handle in enumerate(handles):
            line = handle.readline()
            if line:
                heapq.heappush(heap, (int(line.strip()), idx))

        with open(output_file, "w", encoding="utf-8") as out:
            while heap:
                val, idx = heapq.heappop(heap)
                out.write(f"{val}\n")
                next_line = handles[idx].readline()
                if next_line:
                    heapq.heappush(heap, (int(next_line.strip()), idx))
    finally:
        for handle in handles:
            handle.close()


def external_merge_sort(
    input_file: str,
    output_file: str,
    chunk_size: int = DEFAULT_CHUNK_SIZE,
    work_dir: str | None = None,
) -> None:
    """
    Sort a newline-delimited file of integers that may exceed available memory.

    `work_dir` holds the intermediate runs. When omitted, a temporary directory
    is created and removed afterwards, so nothing is left behind but
    `output_file`. An earlier version wrote `chunk_*.txt` into the current
    working directory, which made the function non-reentrant and littered the
    repository root.

    Time:  O(n log n) comparisons, O(n) I/O across 2 passes
    Space: O(chunk_size) in memory
    """
    owns_work_dir = work_dir is None
    work_dir = work_dir or tempfile.mkdtemp(prefix="extsort_")
    try:
        chunk_files = split_and_sort(input_file, chunk_size, work_dir)
        merge_sorted_files(chunk_files, output_file)
        for path in chunk_files:
            os.remove(path)
    finally:
        if owns_work_dir:
            try:
                os.rmdir(work_dir)
            except OSError:
                pass
